"""Measured extension tables and a causal-ablation figure."""
import json
from pathlib import Path
import numpy as np,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
R=Path('research2/results');rows=json.loads((R/'extension-timings.json').read_text())['groups'];chains={r['tokens']:r for r in json.loads((R/'update-chain-study.json').read_text())};snapshot=json.loads((R/'snapshot-read-study.json').read_text());summary=[];text='# Update chains and observable snapshots\n\nThese extension measurements are a separate isolated CPU run. Compilation and output downloads are excluded; wrong stock snapshot code is not timed. See README.md for calibration and holdout methodology.\n\n|Case|Best correct baseline µs|Old masked form µs|Coalescing alone µs|Combined masked µs|Speedup (95% bootstrap)|\n|---|---:|---:|---:|---:|---:|\n'
for r in rows:
 med=r['holdout']['median_us'];samples=r['holdout']['samples_us'];base=r['best_baseline'];opt=r['patch_key'];rng=np.random.default_rng(628);b=np.array(samples[base]);o=np.array(samples[opt]);ratios=np.median(b[rng.integers(0,len(b),(2000,len(b)))],axis=1)/np.median(o[rng.integers(0,len(o),(2000,len(o)))],axis=1);lo,hi=np.quantile(ratios,[.025,.975]);label='T'+str(r['case']) if r['family']=='chain' else 'Snapshot';stats=chains[r['case']]['variants'] if r['family']=='chain' else snapshot['variants'];item={'case':label,'baseline':base,'baseline_us':med[base],'optimized_us':med[opt],'speedup':r['patch_speedup'],'ci95':[float(lo),float(hi)],'baseline_allocation_bytes':stats[base]['allocated_bytes'],'optimized_allocation_bytes':stats[opt]['allocated_bytes']};summary.append(item);old=f"{med['masked']:.2f}" if r['family']=='chain' else 'incorrect without protection';alone=f"{med['coalesced']:.2f}" if r['family']=='chain' else '—';text+=f"|{label}|{med[base]:.2f}|{old}|{alone}|{med[opt]:.2f}|{r['patch_speedup']:.2f}× ({lo:.2f}–{hi:.2f})|\n"
text+='\nAt T1, coalescing is a no-op and the existing forwarding rewrite already works. At T4–T16, the earlier rewrites do not match the update chains; coalescing makes the single-update representation available. Coalescing alone adds small temporary buffers and is not a speedup claim. Its benefit requires composition with forwarding.\n\n|Case|Best-baseline invocation bytes|Combined invocation bytes|\n|---|---:|---:|\n'
for r in summary:text+=f"|{r['case']}|{r['baseline_allocation_bytes']}|{r['optimized_allocation_bytes']}|\n"
text+='\nThe snapshot case returns the pre-update K/V tensors. Stock IREE corrupts those declared outputs. Correct baselines include both early snapshot protection and the independently compiled Stream COW repair, with stronger fusion controls. The optimized form preserves the old caches while computing attention directly from the base/update rows, avoiding a full temporary cache. No speedup is computed against incorrect stock code.\n\nThe native failure also occurs with the separately installed IREE3.12.0 compiler. The first affected revision is not established. Seven compiler passes are compiled and exercised via the standalone MLIR bridge; the proposed in-tree patches have not both been built into a complete source compiler. GPU compilation is separate from GPU execution.\n\n![Ablation](results/figures/extension-ablation.png)\n'
Path('research2/EXTENSIONS.md').write_text(text);(R/'extension-summary.json').write_text(json.dumps(summary,indent=2));fig,ax=plt.subplots(figsize=(9,3.8));x=np.arange(len(rows));width=.25
ax.bar(x-width,[r['holdout']['median_us'][r['best_baseline']] for r in rows],width,label='Best correct baseline');ax.bar(x,[r['holdout']['median_us'].get('coalesced',r['holdout']['median_us']['protected']) if r['family']=='snapshot' else r['holdout']['median_us']['coalesced'] for r in rows],width,label='Coalescing alone / snapshot protection');ax.bar(x+width,[r['holdout']['median_us'][r['patch_key']] for r in rows],width,label='Combined forwarding');ax.set_xticks(x,[s['case'] for s in summary]);ax.set_ylabel('Median CPU invocation latency (µs)');ax.legend(fontsize=8,loc='lower center',bbox_to_anchor=(.5,1.02));ax.grid(axis='y',alpha=.2);fig.tight_layout();fig.savefig(R/'figures/extension-ablation.png',dpi=180);fig.savefig(R/'figures/extension-ablation.svg');print('Analyzed',len(rows))

svg=R/'figures/extension-ablation.svg'
svg.write_text('\n'.join(line.rstrip() for line in svg.read_text().splitlines())+'\n')
